validator:
function validate(input) {
  const [{ Person = [] }] = input;
  const jobs = ['Doctor', 'Singer', 'Actor', 'Player', 'Engineer', 'Lawyer'];
  const ids = new Set();
  for (const [id, name, profession] of Person) {
    if (id === null || name === null || profession === null) return 'person_id, name and profession are required.';
    if (ids.has(id)) return `person_id ${id} appears twice in Person.`;
    ids.add(id);
    if (!jobs.includes(profession)) return `Unknown profession ${profession}.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const names = ['Alex', 'Alice', 'Bob', 'Messi', 'Tyson', 'Meir', 'Zoe', 'Ana Lee'];
  const jobs = ['Doctor', 'Singer', 'Actor', 'Player', 'Engineer', 'Lawyer'];
  const count = size === 'small' ? pick(9) : 2000;
  const span = size === 'small' ? 20 : 100000;
  const ids = new Set();
  while (ids.size < count) ids.add(1 + pick(span));
  // Ids are inserted in random order so the required ordering is never free.
  const Person = [...ids].map(id => [id, names[pick(names.length)], jobs[pick(jobs.length)]]);
  return [{ Person }];
}
